package com.dixitdada.journalApp.service; import lombok.RequiredArgsConstructor; import org.springframework.data.redis.core.RedisTemplate; import org.springframework.stereotype.Service; import java.time.Duration; @Service @RequiredArgsConstructor public class RedisCacheService { private final RedisTemplate<String,String> redis; public void put(String k,String v,Duration ttl){redis.opsForValue().set(k,v,ttl);} public String get(String k){return redis.opsForValue().get(k);} }